const cp = require("child_process");
// Node.js's child_process (synchronous forms) from an npm package. Prints what it found; the
// same package under Node.js prints the same.
module.exports = function run() {
  const r = cp.spawnSync("sh", ["-c", "echo out; echo err >&2; exit 3"]);
  console.log("spawnSync", r.status, r.signal, r.stdout.toString().trim(), r.stderr.toString().trim(), r.pid > 0, r.output.length);
  console.log("encoding", JSON.stringify(cp.spawnSync("printf", ["a b"], { encoding: "utf8" }).stdout));
  console.log("input", cp.spawnSync("cat", { input: "fed in" }).stdout.toString());
  console.log("execSync", JSON.stringify(cp.execSync("echo $GREETING", { env: { ...process.env, GREETING: "hi" } }).toString()));
  console.log("execFileSync", cp.execFileSync("node-does-not-matter-" === "x" ? "" : "printf", ["%s-%s", "x", "y"]).toString());
  console.log("cwd", cp.execSync("pwd", { cwd: "/", encoding: "utf8" }).trim());
  try {
    cp.execSync("exit 7", { stdio: "pipe" });
  } catch (e) {
    console.log("exit code", e.status, e.message.split("\n")[0]);
  }
  const t = cp.spawnSync("sleep", ["5"], { timeout: 100 });
  console.log("timeout", t.status, t.signal, t.error && t.error.code);
  const m = cp.spawnSync("sh", ["-c", "yes | head -c 100000"], { maxBuffer: 10 });
  console.log("maxBuffer", m.signal, m.error && m.error.code);
  const n = cp.spawnSync("nonexistent-cmd-barm");
  console.log("missing", n.error.code, n.error.syscall, n.error.path, n.status, n.pid);
  console.log("ignore", JSON.stringify(cp.spawnSync("echo", ["x"], { stdio: "ignore" }).output));
  const s = cp.spawnSync("sh", ["-c", "kill -9 $$"]);
  console.log("signal", s.status, s.signal);
};
// the asynchronous forms
module.exports.runAsync = async function runAsync() {
  const events = [];
  await new Promise((resolve) => {
    const child = cp.spawn("sh", ["-c", "read line; echo got:$line; echo warn >&2; exit 4"]);
    let out = "";
    let err = "";
    child.stdout.on("data", (d) => { out += d; });
    child.stderr.on("data", (d) => { err += d; });
    child.on("spawn", () => events.push("spawn"));
    child.on("exit", (code, signal) => events.push(`exit ${code} ${signal}`));
    child.on("close", (code) => {
      events.push(`close ${code}`);
      console.log("spawn", JSON.stringify(out), JSON.stringify(err), events.join(","), child.pid > 0, child.exitCode);
      resolve();
    });
    child.stdin.end("hello\n");
  });
  const { promisify } = require("util");
  const r = await promisify(cp.execFile)("printf", ["%s", "file"]);
  console.log("execFile", JSON.stringify(r));
  const e = await promisify(cp.exec)("echo $((6 * 7))");
  console.log("exec", JSON.stringify(e.stdout), JSON.stringify(e.stderr));
  try {
    await promisify(cp.exec)("echo fail >&2; exit 2");
  } catch (x) {
    console.log("exec error", x.code, JSON.stringify(x.stderr), x.message.split("\n")[0]);
  }
  await new Promise((resolve) => {
    const k = cp.spawn("sleep", ["10"]);
    k.on("exit", (code, signal) => {
      console.log("killed", code, signal, k.killed, k.signalCode);
      resolve();
    });
    k.kill();
  });
  await new Promise((resolve) => {
    const m = cp.spawn("does-not-exist-barm");
    m.on("error", (x) => {
      console.log("spawn error", x.code, x.syscall, x.path);
      resolve();
    });
  });
  await new Promise((resolve) => {
    const big = cp.spawn("sh", ["-c", "head -c 300000 /dev/zero | tr '\\0' a"]);
    let n = 0;
    big.stdout.on("data", (d) => { n += d.length; });
    big.on("close", () => {
      console.log("big output", n);
      resolve();
    });
  });
  await new Promise((resolve) => {
    const cat = cp.spawn("cat");
    let n = 0;
    cat.stdout.on("data", (d) => { n += d.length; });
    cat.on("close", () => {
      console.log("big input", n);
      resolve();
    });
    cat.stdin.write(Buffer.alloc(500000, 98));
    cat.stdin.end();
  });
  const inherit = cp.spawnSync("sh", ["-c", "exit 0"], { stdio: "inherit" });
  console.log("inherit", inherit.status);
};
